/**
 * How long one practice card takes, for every number on screen that turns
 * cards into minutes: Today's "12 cards, about 5 min" and the onboarding
 * plan. One source, so the two never disagree (onboarding v2 spec §6).
 *
 * The server measures it weekly (`GET /config` `plan.secondsPerCard`: the
 * median gap between two answers in one session). Until it has answered,
 * or while it has too little data to say, the app uses the estimate it has
 * always shown: 0.4 of a minute a card.
 */
import { useConfig } from './useConfig.js';

/** The app's estimate before the server measured one: 0.4 min (24 s) a card. */
export const DEFAULT_SECONDS_PER_CARD = 24;

/**
 * The share of reviews answered right, for the plan, before the server
 * measured one (`plan.recall`). 0.9 is the research simulation's middle case
 * (uiux 2026-10-21 research-sim) and the usual Leitner retention; a guess
 * is never shown as data, it only shapes how many new words fit.
 */
export const DEFAULT_RECALL = 0.9;

/** Seconds a card, the server's measure when it has one. */
export function secondsPerCard(): number {
  return useConfig.getState().plan.secondsPerCard ?? DEFAULT_SECONDS_PER_CARD;
}

/** The share of reviews answered right, the server's measure when it has one. */
export function planRecall(): number {
  return useConfig.getState().plan.recall ?? DEFAULT_RECALL;
}

/** Minutes for a number of cards, at least `floor` (Today never promises under 2). */
export function minutesFor(cards: number, floor = 0): number {
  return Math.max(floor, Math.round((cards * secondsPerCard()) / 60));
}
